"""Bounded C89 source behavior; native pointer layout is proved by IDO replay."""
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
ROOT = Path(__file__).resolve().parents[4]
WORK = Path(__file__).resolve().parent
class Semantics(unittest.TestCase):
    def run_c(self, address, body, match=True):
        source = ROOT/'cloud/matches/boot_tail'/('func_'+address+'.c') if match else WORK/'nonmatch'/('func_'+address+'.c')
        with tempfile.TemporaryDirectory() as t:
            p = Path(t)
            (p/'test.c').write_text('#include <assert.h>\n#include <stddef.h>\n#include <string.h>\n#include "'+str(source)+'"\n'+body)
            subprocess.run(['cc','-std=c89','-pedantic-errors','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-no-pie',str(p/'test.c'),'-o',str(p/'test')],check=True,capture_output=True)
            subprocess.run([str(p/'test')],check=True,capture_output=True,env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1'))
    def test_chain_8001B29C(self):
        self.run_c('8001B29C','\nVoiceState D_8004BEB8[4];static u32 lookup;static u8 expected_value;static int calls,mode;static u8 seen[4];\ntypedef char layout[sizeof(VoiceState)==416&&offsetof(VoiceState,next10)==16&&offsetof(VoiceState,channel4B)==75&&offsetof(VoiceState,channel55)==85&&offsetof(VoiceState,identifier60)==96?1:-1];\nu32 func_8001EDF4(u32 key){assert(key==0x12345678U);return lookup;}\nvoid func_80020610(u8 command,u8 index,u8 channel,u8 value){assert(command==10&&index<4&&value==expected_value);assert(channel==((D_8004BEB8[index].flags24&2)?D_8004BEB8[index].channel55:D_8004BEB8[index].channel4B));seen[calls++]=index;if(index==0&&mode)D_8004BEB8[index].next10=mode==1?0xABCDEF02U:0xFFFFFFFFU;}\nint main(void){int mask,flags,i,j,m,expected_count,slot;u8 values[3]={0,127,255};u8 expected_seen[4];for(mask=0;mask<16;mask++)for(flags=0;flags<16;flags++)for(j=0;j<3;j++)for(m=0;m<3;m++){memset(D_8004BEB8,0xA5,sizeof(D_8004BEB8));for(i=0;i<4;i++){D_8004BEB8[i].identifier60=0xABCDEF00U+i+((mask&(1<<i))?0:256);D_8004BEB8[i].next10=i==3?0xFFFFFFFFU:0xABCDEF01U+i;D_8004BEB8[i].flags24=flags&(1<<i)?2:0;D_8004BEB8[i].channel4B=13+i;D_8004BEB8[i].channel55=113+i;}lookup=0xABCDEF00U;expected_value=values[j];calls=0;mode=m;expected_count=0;slot=0;while(slot<4&&(mask&(1<<slot))){expected_seen[expected_count++]=(u8)slot;if(slot==0&&m)slot=m==1?2:4;else slot++;}assert(func_8001B29C(0x12345678U,expected_value)==(expected_count?0:-1));assert(calls==expected_count&&memcmp(seen,expected_seen,(size_t)calls)==0);}lookup=0xFFFFFFFFU;calls=0;assert(func_8001B29C(0x12345678U,0)==-1&&calls==0);return 0;}\n',True)
